  "version": "0.8.0",
  "description": "The frame's conformance script: drives a renderer by keys, by a remapped keymap and by the mouse, and holds what it laid out to the frame, to the other renderers and to the approved golden.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
