import { sameJson, type Intent, type Json } from "@amykit/ui";
import { buildKeymap, type ConformanceRenderer, type Frame, type KeyOverrides, type Mode } from "@amykit/ui/frame";
import type { Finding } from "./checks.js";
import { scene, START, type ConformanceConfig } from "./world.js";

/** The count every normal-mode binding is pressed with once more, the way `3j` is. */
const COUNT = 3;

const said = (intents: readonly Intent[]): string =>
  intents.length === 0 ? "nothing" : intents.map((intent) => `${intent.action}${Object.keys(intent.args).length === 0 ? "" : ` ${JSON.stringify(intent.args)}`}`).join(", ");

/**
 * Every binding and every gesture the frame declares, each in a session of
 * its own, so a key the script never presses is held to the frame as well:
 * each key once, each normal-mode key again after a count, each gesture once.
 */
export function audit(frame: Frame, renderer: ConformanceRenderer, config: ConformanceConfig, keys: KeyOverrides | undefined, run: string): Finding[] {
  const keymap = buildKeymap(frame, keys);
  const findings: Finding[] = [];
  const expect = (did: string, got: readonly Intent[], action: string, args: { readonly [key: string]: Json }): void => {
    if (got.length === 1 && got[0]?.action === action && sameJson(got[0].args, args)) return;
    findings.push({ assertion: "frame.every_key_does_what_it_is_declared_to", renderer: renderer.name, run, message: `${did} did ${said(got)}; the frame declares ${said([{ action, args }])}` });
  };
  const fresh = (mode: Mode) => {
    const session = renderer.start({ frame, ...(keys === undefined ? {} : { keys }) });
    session.draw(scene(frame, { ...START, mode }, config));
    return session;
  };
  for (const mode of ["normal", "insert"] as const) {
    for (const binding of keymap.bindings[mode]) {
      const session = fresh(mode);
      expect(`${binding.keys.join("")} in ${mode} mode, on its own,`, binding.keys.flatMap((key) => session.press(key)), binding.action, {});
      // After a count, 0 is one more digit of it, as in Neovim: a binding that begins with 0 takes no count.
      if (mode !== "normal" || binding.keys[0] === "0") continue;
      const counted = fresh(mode);
      const pressed = [String(COUNT), ...binding.keys].flatMap((key) => counted.press(key));
      expect(`${COUNT}${binding.keys.join("")} in normal mode`, pressed, binding.action, { count: COUNT });
    }
  }
  for (const [gesture, targets] of Object.entries(frame.mouse)) {
    for (const [on, action] of Object.entries(targets)) {
      expect(`${gesture} on ${on}, on its own,`, fresh("normal").pointer({ gesture, on, args: {} }), action, {});
    }
  }
  return findings;
}

import type { Json, Node } from "@amykit/ui";
import type { Box, ConformanceRenderer, Frame, LaidRegion, LaidSurface, Region, Scene, Size } from "@amykit/ui/frame";
import type { Projection } from "./projection.js";
import { CONTRIBUTIONS, sectionOrder, slotOf, tabOrder, type ConformanceConfig } from "./world.js";

/** Every assertion the conformance script makes, by the name a gate requires it under. */
export const ASSERTIONS = [
  "frame.every_region_sits_where_declared",
  "frame.no_region_is_invented",
  "frame.every_key_does_what_it_is_declared_to",
  "frame.renderers_agree_on_every_region",
  "frame.nothing_moved_since_it_was_approved",
  "frame.a_slot_takes_only_what_it_declares",
  "frame.the_fixed_sections_come_first",
  "frame.no_region_is_lost_at_the_narrowest_width",
  "frame.keys_remaps_and_the_mouse_agree",
  "frame.a_surface_is_drawn_only_where_declared",
  "frame.a_projection_is_deterministic",
] as const;

export type Assertion = (typeof ASSERTIONS)[number];

/** One way a renderer is not the window that was agreed, said where it was seen. */
export interface Finding {
  readonly assertion: Assertion;
  readonly renderer: string;
  readonly run?: string;
  readonly step?: string;
  readonly message: string;
}

/** What one step is checked against: the renderer, the step it was on, and what it was handed. */
export interface StepContext {
  readonly frame: Frame;
  readonly renderer: ConformanceRenderer;
  readonly run: string;
  readonly step: string;
  /** The narrowest window the frame allows, in the renderer's unit, when this step resized to it. */
  readonly narrowest?: Size;
  readonly scene: Scene;
  readonly config: ConformanceConfig;
}

type Say = (assertion: Assertion, message: string) => Finding;

const sayer = (context: StepContext): Say => (assertion, message) => ({
  assertion,
  renderer: context.renderer.name,
  run: context.run,
  step: context.step,
  message,
});

const leftOf = (a: Box, b: Box): boolean => a.x + a.width <= b.x;
const above = (a: Box, b: Box): boolean => a.y + a.height <= b.y;
const overlaps = (a: Box, b: Box): boolean =>
  a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height;
const tiled = (region: Region): boolean => region.place !== "overlay";

/** Whether the frame wants a region drawn right now: always, or while toggled on or open. */
function wanted(region: Region, scene: Scene): boolean {
  return region.toggled || region.openedBy !== undefined ? scene.regions[region.name]?.open === true : true;
}

interface Placed {
  readonly region: Region;
  readonly box: Box;
}

/** Per place, the relations it promises against the other drawn regions, each one that fails said as a sentence. */
const PLACEMENT: Readonly<Record<Region["place"], (self: Placed, others: readonly Placed[], of: Placed | undefined) => readonly string[]>> = {
  left: (self, others) =>
    others.flatMap((other) => (leftOf(self.box, other.box) ? [] : [`is declared left, and is not left of ${other.region.name}`])),
  top: (self, others) =>
    others.flatMap((other) => {
      if (other.region.place === "left") return leftOf(other.box, self.box) ? [] : [`is declared at the top of the right column, and is not right of ${other.region.name}`];
      return above(self.box, other.box) ? [] : [`is declared at the top of the right column, and is not above ${other.region.name}`];
    }),
  below: (self, _others, of) => (of === undefined || above(of.box, self.box) ? [] : [`is declared below ${of.region.name}, and is not`]),
  right: (self, _others, of) => (of === undefined || leftOf(of.box, self.box) ? [] : [`is declared right of ${of.region.name}, and is not`]),
  overlay: (self, others) => (others.some((other) => overlaps(self.box, other.box)) ? [] : ["is declared an overlay, and covers nothing"]),
};

/** Each relation one region's placement promises that its box breaks. */
function promises(self: Placed, drawn: readonly Placed[], height: number): readonly string[] {
  const others = drawn.filter((other) => other.region.name !== self.region.name && tiled(other.region));
  const of = drawn.find((other) => other.region.name === self.region.of);
  const tall = !self.region.fullHeight || (self.box.y === 0 && self.box.height === height);
  return [...PLACEMENT[self.region.place](self, others, of), ...(tall ? [] : ["is declared to span the full height, and does not"])];
}

/** Each name a list carries more than once. */
const twice = (names: readonly string[]): readonly string[] => [...new Set(names.filter((name, i) => names.indexOf(name) !== i))];

function checkHolds(region: Region, laid: LaidRegion, say: Say): Finding[] {
  const invented = laid.holds.filter((hold) => !region.holds.includes(hold.name));
  const doubled = twice(laid.holds.map((hold) => hold.name)).map((name) => say("frame.no_region_is_invented", `${region.name} holds ${name} twice`));
  const names = laid.holds.map((hold) => hold.name).filter((name) => region.holds.includes(name));
  return [
    ...invented.map((hold) => say("frame.no_region_is_invented", `${region.name} holds ${hold.name}, which the frame does not declare`)),
    ...doubled,
    ...(names.join() === region.holds.join()
      ? []
      : [say("frame.every_region_sits_where_declared", `${region.name} holds [${names.join(", ")}]; the frame declares [${region.holds.join(", ")}]`)]),
  ];
}

/** At the narrowest width, a region that is not there is a region lost there. */
const loser = (context: StepContext, say: Say): Say => (assertion, message) =>
  say(context.narrowest === undefined ? assertion : "frame.no_region_is_lost_at_the_narrowest_width", message);

const finite = (...values: readonly number[]): boolean => values.every((value) => Number.isFinite(value));

/** Whether a box lies wholly within the surface it was drawn on. */
function inside(box: Box, size: Size): boolean {
  return finite(box.x, box.y, box.width, box.height) && box.x >= 0 && box.y >= 0 && box.x + box.width <= size.width && box.y + box.height <= size.height;
}

/** One declared region, against whether it should be drawn now and where its placement says it sits. */
function checkRegion(context: StepContext, region: Region, drawn: readonly (Placed & { laid: LaidRegion })[], surface: LaidSurface, say: Say): Finding[] {
  const lost = loser(context, say);
  const here = drawn.find((each) => each.region.name === region.name);
  const want = wanted(region, context.scene);
  if (here === undefined) return want ? [lost("frame.every_region_sits_where_declared", `${region.name} should be drawn now, and is not`)] : [];
  return [
    ...(want ? [] : [say("frame.every_region_sits_where_declared", `${region.name} is drawn while it is ${region.toggled ? "toggled off" : "closed"}`)]),
    ...(here.box.width > 0 && here.box.height > 0 ? [] : [lost("frame.every_region_sits_where_declared", `${region.name} is drawn with no room`)]),
    ...(inside(here.box, surface.size) ? [] : [lost("frame.every_region_sits_where_declared", `${region.name} is drawn outside the ${surface.size.width}×${surface.size.height} window`)]),
    ...promises(here, drawn, surface.size.height).map((broken) => say("frame.every_region_sits_where_declared", `${region.name} ${broken}`)),
    ...checkHolds(region, here.laid, say),
  ];
}

/** The frame holds on one surface: every region drawn when it should be, none other, each where it is declared. */
function checkRegions(context: StepContext, surface: LaidSurface, say: Say): Finding[] {
  const { frame } = context;
  const invented = surface.regions
    .filter((laid) => !frame.regions.some((region) => region.name === laid.name))
    .map((laid) => say("frame.no_region_is_invented", `${laid.name} is drawn, and the frame declares no such region`));
  invented.push(...twice(surface.regions.map((laid) => laid.name)).map((name) => say("frame.no_region_is_invented", `${name} is drawn twice`)));
  const drawn = frame.regions.flatMap((region) => {
    const laid = surface.regions.find((each) => each.name === region.name);
    return laid === undefined ? [] : [{ region, box: laid.box, laid }];
  });
  const { narrowest } = context;
  const resized =
    narrowest === undefined || (surface.size.width === narrowest.width && surface.size.height === narrowest.height)
      ? []
      : [loser(context, say)("frame.every_region_sits_where_declared", `the window is ${surface.size.width}×${surface.size.height}, not the narrowest ${narrowest.width}×${narrowest.height} it was resized to`)];
  return [...invented, ...resized, ...frame.regions.flatMap((region) => checkRegion(context, region, drawn, surface, say))];
}

/** Every exact text a tree carries: its text, its string properties, an intent's arguments. */
function texts(value: Json | Node, into: string[] = []): string[] {
  if (typeof value === "string") into.push(value);
  else if (Array.isArray(value)) for (const item of value as readonly Json[]) texts(item, into);
  else if (typeof value === "object" && value !== null) for (const item of Object.values(value)) texts(item as Json, into);
  return into;
}

function tabsIn(tree: Node): readonly string[] {
  const intent = tree.props.intent as { action?: Json; args?: { tab?: Json } } | undefined;
  const own = tree.type === "Button" && intent?.action === "tab.select" ? [String(intent.args?.tab)] : [];
  return [...own, ...tree.children.flatMap((child) => (typeof child === "string" ? [] : tabsIn(child)))];
}

/** Where a contribution is drawn outside the slot the frame gives its collection. */
function strays(context: StepContext, surface: LaidSurface, collection: string, mark: string, say: Say): Finding[] {
  const slot = slotOf(context.frame, collection);
  const where = slot === undefined ? "nowhere" : [slot.region, slot.hold].filter(Boolean).join("/");
  return surface.regions.flatMap((region) =>
    region.holds.flatMap((hold) => {
      if (!texts(hold.tree).includes(mark)) return [];
      const inSlot = slot !== undefined && slot.region === region.name && (slot.hold === undefined || slot.hold === hold.name);
      return inSlot ? [] : [say("frame.a_slot_takes_only_what_it_declares", `${collection}'s ${mark} is drawn in ${region.name}/${hold.name}; its slot is ${where}`)];
    }),
  );
}

/** A contribution the scene put in its slot, and the renderer left out of it. */
function dropped(context: StepContext, surface: LaidSurface, collection: string, mark: string, say: Say): Finding[] {
  const slot = slotOf(context.frame, collection);
  if (slot === undefined) return [];
  const given = context.scene.regions[slot.region];
  const holds = (names: readonly string[]): readonly string[] => (slot.hold === undefined ? names : names.filter((name) => name === slot.hold));
  const sent = given?.open === true && holds(Object.keys(given.holds)).some((name) => texts(given.holds[name] as Node).includes(mark));
  const region = surface.regions.find((each) => each.name === slot.region);
  if (!sent || region === undefined) return [];
  const drawn = region.holds.some((hold) => holds([hold.name]).length > 0 && texts(hold.tree).includes(mark));
  const where = [slot.region, slot.hold].filter(Boolean).join("/");
  return drawn ? [] : [say("frame.a_slot_takes_only_what_it_declares", `${collection}'s ${mark} was handed to ${where}, and is not drawn there`)];
}

/** A plugin's contribution is drawn in its slot and nowhere else; a plugin tab comes after the fixed tabs. */
function checkSlots(context: StepContext, surface: LaidSurface, say: Say): Finding[] {
  const findings = CONTRIBUTIONS.flatMap(({ collection, mark }) => [
    ...strays(context, surface, collection, mark, say),
    ...dropped(context, surface, collection, mark, say),
  ]);
  const tabs = slotOf(context.frame, "ui-tab");
  const held = surface.regions.find((region) => region.name === tabs?.region)?.holds.find((hold) => hold.name === tabs?.hold);
  const order = held === undefined ? [] : tabsIn(held.tree);
  const declared = tabOrder(context.frame);
  if (held !== undefined && order.join() !== declared.join()) {
    findings.push(say("frame.a_slot_takes_only_what_it_declares", `canvas tabs are [${order.join(", ")}]; the frame declares [${declared.join(", ")}]`));
  }
  return findings;
}

/** A surface is drawn only where the renderer declared it, the frame names it, and with only the primitives it holds. */
function checkSurfaces(context: StepContext, surfaces: Readonly<Record<string, LaidSurface>>, say: Say): Finding[] {
  const findings: Finding[] = [];
  if (!context.renderer.surfaces.some((declared) => context.frame.surfaces.some((surface) => surface.name === declared))) {
    findings.push(say("frame.a_surface_is_drawn_only_where_declared", "declares no surface the frame names, so nothing of it could be measured"));
  }
  for (const declared of context.renderer.surfaces) {
    if (!context.frame.surfaces.some((surface) => surface.name === declared)) findings.push(say("frame.a_surface_is_drawn_only_where_declared", `declares ${declared}, which the frame does not name`));
    else if (surfaces[declared] === undefined) findings.push(say("frame.a_surface_is_drawn_only_where_declared", `declares ${declared}, and does not draw it`));
  }
  for (const [name, laid] of Object.entries(surfaces)) {
    const surface = context.frame.surfaces.find((each) => each.name === name);
    if (!context.renderer.surfaces.includes(name) || surface === undefined) {
      findings.push(say("frame.a_surface_is_drawn_only_where_declared", `draws ${name}, which it does not declare`));
      continue;
    }
    for (const region of laid.regions) {
      for (const hold of region.holds) {
        const stray = primitives(hold.tree).find((type) => !(surface.holds as readonly string[]).includes(type));
        if (stray !== undefined) findings.push(say("frame.a_surface_is_drawn_only_where_declared", `${name} draws a ${stray}, which it does not hold`));
      }
    }
  }
  return findings;
}

const primitives = (tree: Node): readonly string[] => [tree.type, ...tree.children.flatMap((child) => (typeof child === "string" ? [] : primitives(child)))];

/** Every check that reads one step of one run on its own. */
export function checkStep(context: StepContext, surfaces: Readonly<Record<string, LaidSurface>>, projection: Projection): Finding[] {
  const say = sayer(context);
  const window = surfaces.window;
  const expected = sectionOrder(context.frame, context.config);
  // The window's own checks only for a renderer that declares one; not drawing it is checkSurfaces' finding.
  if (!context.renderer.surfaces.includes("window") || window === undefined) return checkSurfaces(context, surfaces, say);
  return [
    ...checkSurfaces(context, surfaces, say),
    ...checkRegions(context, window, say),
    ...checkSlots(context, window, say),
    ...(projection.sections.join() === expected.join()
      ? []
      : [say("frame.the_fixed_sections_come_first", `nav 1 offers [${projection.sections.join(", ")}]; the frame and the config give [${expected.join(", ")}]`)]),
  ];
}

#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { approve, conform } from "./conform.js";
import { discover, FILES, goldenText, loadConformance, loadFrame, loadGolden, renderersIn } from "./files.js";

/**
 * amy-ui-conformance: drive every renderer in a workspace through the frame's
 * script and fail, naming what broke, unless each one is the window that was
 * agreed.
 *
 *   --root <dir>      the workspace whose plugins/ui-* are measured (default: here)
 *   --renderer <file> measure the renderers this module exports instead; repeatable
 *   --report <file>   also write the report as JSON
 *   --approve         write the first renderer's projections as the approved golden
 */
interface Options {
  readonly root: string;
  readonly renderers: readonly string[];
  readonly report?: string;
  readonly approve: boolean;
}

function options(argv: readonly string[]): Options {
  let root = process.cwd();
  const renderers: string[] = [];
  let report: string | undefined;
  let approve = false;
  for (let i = 0; i < argv.length; i++) {
    const flag = argv[i];
    const value = argv[i + 1];
    if (flag === "--approve") approve = true;
    else if (value === undefined) throw new TypeError(`${flag} needs a value`);
    else if (flag === "--root") root = value;
    else if (flag === "--renderer") renderers.push(value);
    else if (flag === "--report") report = value;
    else throw new TypeError(`${flag} is not an option`);
    if (flag !== "--approve") i += 1;
  }
  return { root, renderers, approve, ...(report === undefined ? {} : { report }) };
}

async function main(): Promise<number> {
  const { root, renderers: modules, report: reportFile, approve: approving } = options(process.argv.slice(2));
  const frame = loadFrame();
  const renderers = modules.length > 0 ? (await Promise.all(modules.map(renderersIn))).flat() : await discover(path.resolve(root));
  if (renderers.length === 0) {
    console.error(`amy-ui-conformance: no renderer to measure under ${path.resolve(root)}`);
    return 1;
  }
  const config = loadConformance();
  if (approving) {
    // Only a window that holds the frame in every other way may become the approved one.
    const approval = approve(frame, renderers, config, loadGolden());
    if ("refused" in approval) {
      console.error(`amy-ui-conformance: not approved, and ${FILES.golden} is untouched:`);
      for (const reason of approval.refused) console.error(`  ${reason}`);
      return 1;
    }
    fs.writeFileSync(FILES.golden, goldenText(approval.golden));
    console.log(`approved ${approval.golden.steps.length} projections into ${FILES.golden}; lock it with \`sf lock\``);
  }
  const report = conform(frame, renderers, config, loadGolden());
  if (reportFile !== undefined) fs.writeFileSync(reportFile, `${JSON.stringify(report, null, 2)}\n`);
  for (const finding of report.findings) {
    const where = [finding.renderer, finding.run, finding.step].filter(Boolean).join(" · ");
    console.error(`${finding.assertion}: ${where}: ${finding.message}`);
  }
  const names = report.renderers.map((renderer) => renderer.name).join(", ");
  if (report.findings.length > 0) {
    console.error(`\n${report.findings.length} finding(s) across ${names}: the window is not the one the frame declares`);
    return 1;
  }
  console.log(`${names}: every assertion of the frame holds, three ways and twice`);
  return 0;
}

main().then(
  (code) => process.exit(code),
  (error: unknown) => {
    console.error(`amy-ui-conformance: ${error instanceof Error ? error.message : String(error)}`);
    process.exit(2);
  },
);

import { sameJson, type Intent } from "@amykit/ui";
import { buildKeymap, keysFor, type ConformanceRenderer, type Frame, type KeyOverrides, type Session, type Size } from "@amykit/ui/frame";
import { audit } from "./audit.js";
import { ASSERTIONS, checkStep, type Assertion, type Finding } from "./checks.js";
import { firstDifference, project, type Projection } from "./projection.js";
import { RUNS, SCRIPT, type Move, type Run, type Step } from "./script.js";
import { apply, scene, START, type ConformanceConfig, type WindowState } from "./world.js";

/** The conformance config: what the world's config gives, and the keymap the remapped run uses. */
export interface Conformance extends ConformanceConfig {
  readonly keys: KeyOverrides;
}

export interface Golden {
  readonly steps: readonly Projection[];
}

export interface Report {
  readonly renderers: readonly { readonly name: string; readonly unit: string; readonly surfaces: readonly string[] }[];
  readonly assertions: readonly { readonly type: Assertion; readonly status: "passed" | "failed"; readonly findings: number }[];
  readonly findings: readonly Finding[];
  /** Each renderer's projections, driven by the default keys. */
  readonly projections: Readonly<Record<string, readonly Projection[]>>;
}

interface Driven {
  readonly projections: readonly Projection[];
  readonly findings: readonly Finding[];
}

interface Drive {
  readonly frame: Frame;
  readonly renderer: ConformanceRenderer;
  readonly run: Run;
  readonly config: Conformance;
}

/** What the frame says one move should make the renderer ask for. */
function perform(drive: Drive, session: Session, move: Move, state: WindowState, keymap: ReturnType<typeof buildKeymap>): { got: readonly Intent[]; want: Intent; did: string } {
  const gesture = drive.run === "mouse" ? move.mouse : undefined;
  if (gesture !== undefined) {
    const action = drive.frame.mouse[gesture.gesture]?.[gesture.on] ?? "(no action)";
    return { got: session.pointer(gesture), want: { action, args: gesture.args }, did: `${gesture.gesture} on ${gesture.on}` };
  }
  const keys = keysFor(keymap, state.mode, move.action);
  if (keys === undefined) return { got: [], want: { action: move.action, args: {} }, did: `no key for ${move.action} in ${state.mode} mode` };
  return { got: keys.flatMap((key) => session.press(key)), want: { action: move.action, args: {} }, did: `${keys.join("")} in ${state.mode} mode` };
}

const describe = (intents: readonly Intent[]): string => (intents.length === 0 ? "nothing" : intents.map((intent) => intent.action).join(", "));

/** Whether what the renderer asked for is exactly the one intent the frame says this move asks for. */
const asked = (got: readonly Intent[], want: Intent): boolean => got.length === 1 && got[0]?.action === want.action && sameJson(got[0].args, want.args);

/** Where the last step takes the window: the narrowest the frame allows, in the renderer's unit. */
const narrowestFor = (frame: Frame, renderer: ConformanceRenderer, step: Step): Size | undefined =>
  step.narrowest ? (renderer.unit === "px" ? frame.narrowest.px : frame.narrowest.cells) : undefined;

/** The script once, through one renderer, one way: a projection per step and whatever each step broke. */
function driveOnce(drive: Drive): Driven {
  const { frame, renderer, run, config } = drive;
  const overrides = run === "remapped keys" ? config.keys : undefined;
  const keymap = buildKeymap(frame, overrides);
  const session = renderer.start({ frame, ...(overrides === undefined ? {} : { keys: overrides }) });
  let state = START;
  session.draw(scene(frame, state, config));
  const projections: Projection[] = [];
  const findings: Finding[] = [];
  for (const step of SCRIPT) {
    for (const move of step.moves) {
      const { got, want, did } = perform(drive, session, move, state, keymap);
      if (!asked(got, want)) {
        findings.push({ assertion: "frame.every_key_does_what_it_is_declared_to", renderer: renderer.name, run, step: step.name, message: `${did} did ${describe(got)}; the frame declares ${want.action}` });
      }
      for (const intent of got) state = apply(state, intent, frame, config);
      session.draw(scene(frame, state, config));
    }
    const narrowest = narrowestFor(frame, renderer, step);
    if (narrowest !== undefined) session.resize(narrowest);
    const laid = session.read();
    const projection = project(frame, step.name, state.mode, laid);
    const context = { frame, renderer, run, step: step.name, ...(narrowest === undefined ? {} : { narrowest }), scene: scene(frame, state, config), config };
    findings.push(...checkStep(context, laid.surfaces, projection));
    projections.push(projection);
  }
  return { projections, findings };
}

/** Step by step, both ways round: a step either side lacks is a difference too. */
function compare(frame: Frame, a: readonly Projection[], b: readonly Projection[], say: (step: string, where: string) => Finding): Finding[] {
  return Array.from({ length: Math.max(a.length, b.length) }, (_, i) => [a[i], b[i]] as const).flatMap(([left, right]) => {
    if (left === undefined || right === undefined) {
      const step = (left ?? right)?.step ?? "";
      return [say(step, `${step}: ${left === undefined ? "missing" : "drawn"} ≠ ${right === undefined ? "missing" : "drawn"}`)];
    }
    const where = firstDifference(frame, left, right);
    return where === undefined ? [] : [say(left.step, where)];
  });
}

/** The projections, kept to the surfaces somebody else also drew; nav 1's sections are the window's. */
function within(projections: readonly Projection[], surfaces: readonly string[]): readonly Projection[] {
  return projections.map((projection) => ({
    ...projection,
    sections: surfaces.includes("window") ? projection.sections : [],
    surfaces: Object.fromEntries(Object.entries(projection.surfaces).filter(([name]) => surfaces.includes(name))),
  }));
}

function measure(frame: Frame, renderer: ConformanceRenderer, config: Conformance, golden: Golden | undefined): { keys: readonly Projection[]; findings: Finding[] } {
  const runs = RUNS.map((run) => ({ run, ...driveOnce({ frame, renderer, run, config }) }));
  const keys = runs[0]?.projections ?? [];
  const findings = [
    ...runs.flatMap((driven) => driven.findings),
    ...audit(frame, renderer, config, undefined, "keys"),
    ...audit(frame, renderer, config, config.keys, "remapped keys"),
  ];
  for (const other of runs.slice(1)) {
    findings.push(
      ...compare(frame, keys, other.projections, (step, where) => ({
        assertion: "frame.keys_remaps_and_the_mouse_agree",
        renderer: renderer.name,
        run: other.run,
        step,
        message: `driven by ${other.run}, it differs from the default keys at ${where}`,
      })),
    );
  }
  const repeat = driveOnce({ frame, renderer, run: "keys", config });
  const again = repeat.projections;
  // What the second run broke counts as much as the first: a resize that works once is not a resize.
  findings.push(...repeat.findings.map((finding) => ({ ...finding, run: "keys, again" })));
  if (JSON.stringify(again) !== JSON.stringify(keys)) {
    findings.push({ assertion: "frame.a_projection_is_deterministic", renderer: renderer.name, message: `the same script twice: ${firstDifference(frame, keys, again) ?? "the same values, in different bytes"}` });
  }
  if (golden === undefined) {
    findings.push({ assertion: "frame.nothing_moved_since_it_was_approved", renderer: renderer.name, message: "there is no approved projection to compare with" });
  } else {
    const approved = Object.keys(golden.steps[0]?.surfaces ?? {});
    const shared = renderer.surfaces.filter((name) => approved.includes(name));
    findings.push(
      ...compare(frame, within(keys, shared), within(golden.steps, shared), (step, where) => ({
        assertion: "frame.nothing_moved_since_it_was_approved",
        renderer: renderer.name,
        step,
        message: `differs from the approved projection at ${where}`,
      })),
    );
  }
  return { keys, findings };
}

/** Per surface, every renderer that draws it against the first that does, so two menu bars are compared even when the first renderer draws none. */
function crossCheck(frame: Frame, renderers: readonly ConformanceRenderer[], keys: readonly (readonly Projection[])[]): Finding[] {
  return frame.surfaces.flatMap(({ name }) => {
    const holders = renderers.flatMap((renderer, i) => (renderer.surfaces.includes(name) && (keys[i]?.length ?? 0) > 0 ? [{ renderer, keys: keys[i] ?? [] }] : []));
    const [first, ...rest] = holders;
    if (first === undefined) return [];
    return rest.flatMap((other) =>
      compare(frame, within(first.keys, [name]), within(other.keys, [name]), (step, where) => ({
        assertion: "frame.renderers_agree_on_every_region",
        renderer: other.renderer.name,
        step,
        message: `${first.renderer.name} and ${other.renderer.name} differ first at ${where}`,
      })),
    );
  });
}

/**
 * Every renderer through the script three ways — default keys, a remapped
 * keymap, the mouse — and the default way twice, each step read back from
 * what it laid out and held to the frame, to the other renderers, and to the
 * approved projection.
 */
export function conform(frame: Frame, renderers: readonly ConformanceRenderer[], config: Conformance, golden?: Golden): Report {
  const sorted = [...renderers].sort((a, b) => a.name.localeCompare(b.name));
  const measured = sorted.map((renderer) => {
    try {
      return measure(frame, renderer, config, golden);
    } catch (error) {
      const message = `could not be driven: ${error instanceof Error ? error.message : String(error)}`;
      return { keys: [], findings: [{ assertion: "frame.every_region_sits_where_declared" as const, renderer: renderer.name, message }] };
    }
  });
  const names = sorted.map((renderer) => renderer.name);
  // Projections are kept by name, so two renderers sharing one would be compared, and approved, as one.
  const named = [...new Set(names.filter((name, i) => names.indexOf(name) !== i))].map((name) => ({
    assertion: "frame.renderers_agree_on_every_region" as const,
    renderer: name,
    message: `${names.filter((each) => each === name).length} renderers are named ${name}; each needs a name of its own to be compared`,
  }));
  const findings = [...named, ...measured.flatMap((each) => each.findings), ...crossCheck(frame, sorted, measured.map((each) => each.keys))];
  return {
    renderers: sorted.map((renderer) => ({ name: renderer.name, unit: renderer.unit, surfaces: renderer.surfaces })),
    assertions: ASSERTIONS.map((type) => {
      const count = findings.filter((finding) => finding.assertion === type).length;
      return { type, status: count === 0 && sorted.length > 0 ? "passed" : "failed", findings: count };
    }),
    findings,
    projections: Object.fromEntries(sorted.map((renderer, i) => [renderer.name, measured[i]?.keys ?? []])),
  };
}

/** What `--approve` would write, or why it will not. */
export type Approval = { readonly golden: Golden } | { readonly refused: readonly string[] };

/**
 * The golden a set of renderers would approve: per surface, the projections
 * of the first renderer that draws it, so no surface is approved from a
 * renderer that does not draw it. Refused while anything but the golden
 * fails, while there is nothing to approve, or when a surface the previous
 * golden held is drawn by none of them — approving would drop its baseline.
 */
export function approve(frame: Frame, renderers: readonly ConformanceRenderer[], config: Conformance, previous?: Golden): Approval {
  const draft = conform(frame, renderers, config, undefined);
  const refused = draft.findings
    .filter((finding) => finding.assertion !== "frame.nothing_moved_since_it_was_approved")
    .map((finding) => `${finding.assertion}: ${finding.renderer}: ${finding.message}`);
  const drawers = new Map<string, readonly Projection[]>();
  for (const renderer of draft.renderers) {
    for (const surface of renderer.surfaces) if (!drawers.has(surface)) drawers.set(surface, draft.projections[renderer.name] ?? []);
  }
  const held = Object.keys(previous?.steps[0]?.surfaces ?? {});
  refused.push(...held.filter((surface) => !drawers.has(surface)).map((surface) => `${surface} is in the approved golden, and no renderer here draws it`));
  const window = drawers.get("window") ?? [];
  const first = [...drawers.values()][0] ?? [];
  const steps = first.map((step, i) => ({
    ...step,
    sections: window[i]?.sections ?? [],
    surfaces: Object.fromEntries(
      [...drawers.entries()]
        .sort(([a], [b]) => a.localeCompare(b))
        .flatMap(([surface, projections]) => {
          const projected = projections[i]?.surfaces[surface];
          return projected === undefined ? [] : [[surface, projected]];
        }),
    ),
  }));
  if (steps.length === 0) refused.push("there is no projection to approve");
  return refused.length > 0 ? { refused } : { golden: { steps } };
}

import fs from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { pathToFileURL } from "node:url";
import YAML from "yaml";
import { checkFrame, type ConformanceRenderer, type Frame, type KeyOverrides } from "@amykit/ui/frame";
import type { Conformance, Golden } from "./conform.js";

/** Where @amykit/ui is installed beside this package: the frame and what was approved from it ship there. */
const UI = path.dirname(createRequire(import.meta.url).resolve("@amykit/ui/frame.yaml"));

/** The frame, the conformance config and the approved projection: all three ship with @amykit/ui and are locked. */
export const FILES = {
  frame: path.join(UI, "frame.yaml"),
  config: path.join(UI, "conformance", "config.yaml"),
  golden: path.join(UI, "conformance", "golden.json"),
};

export function loadFrame(file = FILES.frame): Frame {
  return checkFrame(YAML.parse(fs.readFileSync(file, "utf-8")));
}

export function loadConformance(file = FILES.config): Conformance {
  const parsed = YAML.parse(fs.readFileSync(file, "utf-8")) as { ui?: { sections?: string[]; keys?: KeyOverrides } };
  return { ...(parsed.ui?.sections === undefined ? {} : { sections: parsed.ui.sections }), keys: parsed.ui?.keys ?? {} };
}

export function loadGolden(file = FILES.golden): Golden | undefined {
  return fs.existsSync(file) ? (JSON.parse(fs.readFileSync(file, "utf-8")) as Golden) : undefined;
}

/** The approved projection, as the bytes a lock hashes: the same projections are always the same file. */
export function goldenText(golden: Golden): string {
  return `${JSON.stringify(golden, null, 2)}\n`;
}

function isRenderer(value: unknown): value is ConformanceRenderer {
  return typeof value === "object" && value !== null && typeof (value as ConformanceRenderer).start === "function" && typeof (value as ConformanceRenderer).name === "string";
}

/** The renderers a module exports as `renderers`. */
export async function renderersIn(file: string): Promise<readonly ConformanceRenderer[]> {
  const module = (await import(pathToFileURL(path.resolve(file)).href)) as { renderers?: unknown };
  const found = Array.isArray(module.renderers) ? module.renderers : [];
  if (found.length === 0 || !found.every(isRenderer)) throw new TypeError(`${file} exports no conformance renderers`);
  return found;
}

/**
 * Every renderer in a workspace: each `plugins/ui-*` package, through the
 * module its `amy.conformance` names. Until the `ui-renderer` collection
 * exists, this list is the harness's own.
 */
export async function discover(root: string): Promise<readonly ConformanceRenderer[]> {
  const plugins = path.join(root, "plugins");
  if (!fs.existsSync(plugins)) return [];
  const modules = fs
    .readdirSync(plugins)
    .filter((entry) => entry.startsWith("ui-"))
    .sort()
    .flatMap((entry) => {
      const manifest = path.join(plugins, entry, "package.json");
      if (!fs.existsSync(manifest)) return [];
      const conformance = (JSON.parse(fs.readFileSync(manifest, "utf-8")) as { amy?: { conformance?: string } }).amy?.conformance;
      return conformance === undefined ? [] : [path.join(plugins, entry, conformance)];
    });
  return (await Promise.all(modules.map(renderersIn))).flat();
}

export { ASSERTIONS, type Assertion, type Finding } from "./checks.js";
export { approve, conform, type Approval, type Conformance, type Golden, type Report } from "./conform.js";
export { discover, FILES, goldenText, loadConformance, loadFrame, loadGolden, renderersIn } from "./files.js";
export { firstDifference, project, relate, type Projection, type ProjectedRegion, type ProjectedSurface } from "./projection.js";
export { RUNS, SCRIPT, type Move, type Run, type Step } from "./script.js";
export { WORLD } from "./world.js";

import type { Json, Node } from "@amykit/ui";
import { abbreviates, type Box, type Frame, type Laid, type LaidRegion, type LaidSurface, type Mode } from "@amykit/ui/frame";

/**
 * What the harness reads out of what a renderer laid out: per surface, the
 * regions in the frame's order with what each holds, and how every pair of
 * regions sits relative to each other. No box is kept, only relations, so a
 * pixel and a cell compare the same way and a font changes nothing.
 */
export interface ProjectedRegion {
  readonly name: string;
  readonly fullHeight: boolean;
  readonly holds: readonly { readonly name: string; readonly tree: Node }[];
}

export interface ProjectedSurface {
  readonly regions: readonly ProjectedRegion[];
  /** `a left-of b`, `a above b`, `a overlaps b`, for each pair in the frame's order. */
  readonly relations: readonly string[];
}

export interface Projection {
  readonly step: string;
  readonly mode: Mode;
  /** The sections nav 1 offers, in the order it offers them. */
  readonly sections: readonly string[];
  readonly surfaces: Readonly<Record<string, ProjectedSurface>>;
}

const leftOf = (a: Box, b: Box): boolean => a.x + a.width <= b.x;
const above = (a: Box, b: Box): boolean => a.y + a.height <= b.y;
const overlaps = (a: Box, b: Box): boolean =>
  a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height;

/** Every relation that holds between two boxes, in a fixed order. */
export function relate(a: Box, b: Box): readonly string[] {
  const found: string[] = [];
  if (leftOf(a, b)) found.push("left-of");
  if (leftOf(b, a)) found.push("right-of");
  if (above(a, b)) found.push("above");
  if (above(b, a)) found.push("below");
  if (overlaps(a, b)) found.push("overlaps");
  return found;
}

function ordered(frame: Frame, regions: readonly LaidRegion[]): readonly LaidRegion[] {
  const at = (name: string): number => {
    const i = frame.regions.findIndex((region) => region.name === name);
    return i === -1 ? frame.regions.length : i;
  };
  return [...regions].sort((a, b) => at(a.name) - at(b.name) || a.name.localeCompare(b.name));
}

function projectSurface(frame: Frame, surface: LaidSurface): ProjectedSurface {
  const regions = ordered(frame, surface.regions);
  const relations = regions.flatMap((a, i) =>
    regions.slice(i + 1).flatMap((b) => relate(a.box, b.box).map((relation) => `${a.name} ${relation} ${b.name}`)),
  );
  return {
    regions: regions.map((region) => ({
      name: region.name,
      fullHeight: region.box.y === 0 && region.box.height === surface.size.height,
      holds: region.holds,
    })),
    relations,
  };
}

/** The sections a tree offers: each `section.select` intent's section, in order. */
function sectionsIn(tree: Node): readonly string[] {
  const own = tree.type === "Button" && isSelect(tree.props.intent) ? [String((tree.props.intent as { args: { section: Json } }).args.section)] : [];
  return [...own, ...tree.children.flatMap((child) => (typeof child === "string" ? [] : sectionsIn(child)))];
}

function isSelect(intent: Json | undefined): boolean {
  return isObject(intent) && intent.action === "section.select";
}

export function project(frame: Frame, step: string, mode: Mode, laid: Laid): Projection {
  const surfaces = Object.fromEntries(
    Object.entries(laid.surfaces)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([name, surface]) => [name, projectSurface(frame, surface)]),
  );
  const nav = frame.regions.find((region) => region.holds.includes("section"));
  const held = laid.surfaces.window?.regions.find((region) => region.name === nav?.name)?.holds.find((hold) => hold.name === "section");
  return { step, mode, sections: held === undefined ? [] : sectionsIn(held.tree), surfaces };
}

/**
 * Where two projections first differ, as a path and the two values, or
 * nothing when they are the same. A label a person reads — a primitive's text,
 * a title, a placeholder — compares equal to one the frame's abbreviation rule
 * could have shortened it to, either way round; every other string, an
 * intent's action and arguments included, compares exactly.
 */
export function firstDifference(frame: Frame, a: unknown, b: unknown, at = "", role?: Role): string | undefined {
  if (Array.isArray(a) && Array.isArray(b)) return named(a) && named(b) ? byName(frame, a, b, at) : byIndex(frame, a, b, at, role);
  if (isObject(a) && isObject(b)) return byKey(frame, a, b, at);
  return same(frame, a, b, role === "label") ? undefined : `${at}: ${JSON.stringify(a) ?? "missing"} ≠ ${JSON.stringify(b) ?? "missing"}`;
}

/** What a value is to the node holding it: a label shown as it is, or the list of a node's children. */
type Role = "label" | "children";

/** The properties a renderer shows as text, rather than acts on. */
const LABELS = ["title", "placeholder"];

/** Two leaves: equal, or two labels one of which the frame's rule abbreviates to the other. */
function same(frame: Frame, a: unknown, b: unknown, label: boolean): boolean {
  if (!label || typeof a !== "string" || typeof b !== "string") return a === b;
  return abbreviates(frame, a, b) || abbreviates(frame, b, a);
}

function byKey(frame: Frame, a: Readonly<Record<string, unknown>>, b: Readonly<Record<string, unknown>>, at: string): string | undefined {
  for (const key of [...new Set([...Object.keys(a), ...Object.keys(b)])].sort()) {
    const role: Role | undefined = key === "children" ? "children" : LABELS.includes(key) ? "label" : undefined;
    const found = firstDifference(frame, a[key], b[key], `${at}/${key}`, role);
    if (found !== undefined) return found;
  }
  return undefined;
}

const isObject = (value: unknown): value is Readonly<Record<string, unknown>> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

type Named = Readonly<Record<string, unknown>> & { readonly name: string };

/** Regions and holds: a list whose items each carry a name, none twice. */
function named(list: readonly unknown[]): list is readonly Named[] {
  const names = list.map((item) => (isObject(item) && typeof item.name === "string" ? item.name : undefined));
  return names.every((name) => name !== undefined) && new Set(names).size === names.length;
}

const presence = (item: unknown): string => (item === undefined ? "missing" : "drawn");

/** Compared by name, so a region one renderer left out is named, rather than shifting every one after it. */
function byName(frame: Frame, a: readonly Named[], b: readonly Named[], at: string): string | undefined {
  const names = [...new Set([...a, ...b].map((item) => item.name))];
  for (const name of names) {
    const left = a.find((item) => item.name === name);
    const right = b.find((item) => item.name === name);
    if (left === undefined || right === undefined) return `${at}/${name}: ${presence(left)} ≠ ${presence(right)}`;
    const found = firstDifference(frame, left, right, `${at}/${name}`);
    if (found !== undefined) return found;
  }
  const order = (list: readonly Named[]): string => list.map((item) => item.name).join(", ");
  return order(a) === order(b) ? undefined : `${at}: [${order(a)}] ≠ [${order(b)}]`;
}

/** A node's text children are labels; the items of any other list are not. */
function byIndex(frame: Frame, a: readonly unknown[], b: readonly unknown[], at: string, role?: Role): string | undefined {
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    if (i >= a.length || i >= b.length) return `${at}/${i}: ${presence(a[i])} ≠ ${presence(b[i])}`;
    const found = firstDifference(frame, a[i], b[i], `${at}/${i}`, role === "children" ? "label" : undefined);
    if (found !== undefined) return found;
  }
  return undefined;
}

